from html import escape
from pathlib import Path
import json
from delegationflow.core.models import AssessmentResult


def export_html(result: AssessmentResult, output_path: str) -> None:
    rows = []
    for f in result.findings:
        evidence = escape(str(f.evidence))
        recs = "".join(f"<li>{escape(x)}</li>" for x in f.recommendations)
        rows.append(f"<tr><td>{escape(f.finding_id)}</td><td>{escape(f.severity.value)}</td><td>{escape(f.title)}</td><td>{escape(f.status)}</td><td>{escape(f.description)}<details><summary>Evidence</summary><pre>{evidence}</pre></details><ul>{recs}</ul></td></tr>")
    doc = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DelegationFlow Assessment</title><style>
:root{{--bg:#0b1118;--panel:#111c28;--line:#26384a;--text:#e5edf5;--muted:#9aafc3;--accent:#6ea8d8}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,sans-serif}}main{{max-width:1200px;margin:40px auto;padding:0 22px}}header,.panel{{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}}h1{{margin:0;color:var(--accent)}}.meta{{color:var(--muted);overflow-wrap:anywhere}}table{{width:100%;border-collapse:collapse;background:var(--panel);border-radius:12px;overflow:hidden}}th,td{{padding:13px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line)}}th{{color:var(--accent)}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;color:var(--muted)}}summary{{cursor:pointer;color:var(--accent)}}.pill{{font-weight:700}}footer{{color:var(--muted);margin:20px 0}}</style></head><body><main><header><h1>DelegationFlow</h1><div class="meta">Read-only Active Directory security assessment</div><p>Server: {escape(result.server)}<br>Base DN: {escape(result.base_dn)}<br>Generated: {escape(result.generated_at.isoformat())}</p></header><section class="panel"><strong>{len(result.accounts)}</strong> unconstrained delegation accounts &nbsp;·&nbsp; <strong>{len(result.findings)}</strong> findings</section><section class="panel"><h2>Additional Directory Context</h2><pre>{escape(json.dumps(result.context, indent=2, default=str))}</pre></section><table><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Status</th><th>Details</th></tr></thead><tbody>{''.join(rows)}</tbody></table><footer>Generated by DelegationFlow. Findings describe observed configuration and do not establish exploitability.</footer></main></body></html>'''
    Path(output_path).expanduser().write_text(doc, encoding="utf-8")
